CREATE POLICY delete_admin_or_self ON memberships FOR DELETE TO butterbase_user
  USING (((user_id = (current_user_id())::uuid) OR (EXISTS ( SELECT 1
   FROM memberships m2
  WHERE ((m2.user_id = (current_user_id())::uuid) AND (m2.role = ANY (ARRAY['owner'::text, 'admin'::text])))))));

