  WITH CHECK ((EXISTS ( SELECT 1
   FROM memberships m2
  WHERE ((m2.user_id = (current_user_id())::uuid) AND (m2.role = ANY (ARRAY['owner'::text, 'admin'::text]))))));

CREATE POLICY team_member_select ON memberships FOR SELECT TO butterbase_user
  USING ((user_id = (current_user_id())::uuid));

